#!/bin/bash
# Task 075 -- meshsim v1.2 (WORKER4, branch v1.2-meshsim at 2f45c7f): run_tests.sh's quick suite (29 Java steps; the
# tile images, the boot ROM and the replay controller prebuilt), 8 at a time, to close phase 4. The kit (wip/meshsim with
# Java 17 classes, wip/sw's REGISTERS.md and headers, wip/tools/replayer-opcodes; run_quick.sh) is embedded below as a
# base64 tgz, SHA-256 checked; smoke-tested locally (BusTest, NetTest, RegDocTest through run_quick.sh). Commits every
# log and VERDICT.txt. Expected 10-20 min, about 24 GB.
set -u
cd "$(dirname "$0")/.."
RES=$PWD/results/075-meshsim-v12-quick; mkdir -p "$RES"
WANT=75ee5a586217903a69ea25147a44b0e25d51800719d15f1c6845546b6b985c65
W=/tmp/ms-075; rm -rf "$W"; mkdir -p "$W"
sed -n '/^__KIT_BEGIN__$/,/^__KIT_END__$/p' "$0" | sed '1d;$d' | base64 -d > "$W/kit.tgz" || exit 2
GOT=$(sha256sum "$W/kit.tgz" | cut -d' ' -f1); echo "kit sha256 $GOT"
[ "$GOT" = "$WANT" ] || { echo "kit sha256 mismatch (want $WANT)"; exit 2; }
tar -xzf "$W/kit.tgz" -C "$W" || exit 2
cd "$W/wip/meshsim" || exit 2
echo "start $(date -u) on $(hostname), $(nproc) threads"; java -version 2>&1 | head -1
P=8 ./run_quick.sh "$W/out"; RC=$?
echo "run_quick.sh exit $RC at $(date -u)"
cp "$W"/out/* "$RES/" 2>/dev/null
cat "$W/out/VERDICT.txt" 2>/dev/null
exit $RC
